<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$id=filter_var($_POST['application_id']??null,FILTER_VALIDATE_INT);$next=(string)($_POST['to_status']??'');$notes=trim((string)($_POST['notes']??''));$expires=trim((string)($_POST['offer_expires_on']??''));$expiry=null;if($expires!==''){$expiry=DateTimeImmutable::createFromFormat('!Y-m-d',$expires);$errors=DateTimeImmutable::getLastErrors();if($expiry===false||$expiry->format('Y-m-d')!==$expires||($errors!==false&&($errors['warning_count']||$errors['error_count']))||$expires<date('Y-m-d'))$expiry=false;}
if(!$id||!in_array($next,['Under Review','Waitlisted','Offered','Accepted','Declined'],true)||strlen($notes)<5||strlen($notes)>2000||($next==='Offered'&&(!$expiry||$expires===''))||($expires!==''&&!$expiry)){$_SESSION['error']='Choose a valid review decision, include a short decision note, and set an offer expiry date when making an offer.';header('Location: ../?page=admissions');exit;}
$transitions=['Submitted'=>['Under Review','Waitlisted','Declined'],'Under Review'=>['Waitlisted','Offered','Declined'],'Waitlisted'=>['Under Review','Offered','Declined'],'Offered'=>['Under Review','Accepted','Declined'],'Accepted'=>['Declined']];$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT id,status,offer_expires_on,entry_year FROM admission_applications WHERE id=:id FOR UPDATE');$q->execute(['id'=>$id]);$app=$q->fetch();if(!$app)throw new DomainException('Application not found.');if(!in_array($next,$transitions[$app['status']]??[],true))throw new DomainException('This decision is not available from the application’s current status.');if($next==='Accepted'&&$app['offer_expires_on']&&$app['offer_expires_on']<date('Y-m-d'))throw new DomainException('This offer expired. Make a new offer before recording acceptance.');if($next==='Offered'&&(int)$app['entry_year']<(int)date('Y'))throw new DomainException('The entry year has passed; update the application before making an offer.');if($next==='Offered'){$q=$pdo->prepare('UPDATE admission_applications SET status=:status,offer_expires_on=:expires WHERE id=:id');$q->execute(['status'=>$next,'expires'=>$expires,'id'=>$id]);}else{$q=$pdo->prepare('UPDATE admission_applications SET status=:status WHERE id=:id');$q->execute(['status'=>$next,'id'=>$id]);}$q=$pdo->prepare('INSERT INTO admission_status_history(application_id,from_status,to_status,notes,changed_by) VALUES(:id,:from_status,:to_status,:notes,:user)');$q->execute(['id'=>$id,'from_status'=>$app['status'],'to_status'=>$next,'notes'=>$notes,'user'=>$user['id']]);audit_log('admissions.status_changed','admission_applications',$id,['from'=>$app['status'],'to'=>$next]);$pdo->commit();$_SESSION['notice']='Application status updated to '.$next.'.';}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Admission review failed: '.$e->getMessage());$_SESSION['error']='Could not save the application decision.';}header('Location: ../?page=admissions');exit;
